#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE="${ENV_FILE:-.dolby-rro.env}"
TOTAL_STAGES=5

banner "HalcyonDolby device RRO setup"

# Stage 1: target device tree and optional vendor inputs
stage "Device tree and vendor files"
say "Collect target paths so the wizard can inspect your HAL and XML."
ask DEVICE_CODENAME "Device codename (e.g. beryl):"
ask DEVICE_VENDOR "Device vendor (e.g. xiaomi):"
default_tree="device/${DEVICE_VENDOR}/${DEVICE_CODENAME}"
say "Default device tree path: ${default_tree}"
ask DEVICE_TREE_DIR "Device tree path [Enter for ${default_tree}]:"
[[ -z "$DEVICE_TREE_DIR" ]] && DEVICE_TREE_DIR="$default_tree"
ask DAX_XML_PATH "Path to dax-default.xml (optional, Enter to skip):"
ask SWDAP_SO_PATH "Path to libswdapaidl.so (optional, Enter to skip):"
write_env DEVICE_CODENAME "$DEVICE_CODENAME"
write_env DEVICE_VENDOR "$DEVICE_VENDOR"
write_env DEVICE_TREE_DIR "$DEVICE_TREE_DIR"
write_env DAX_XML_PATH "$DAX_XML_PATH"
write_env SWDAP_SO_PATH "$SWDAP_SO_PATH"

# Stage 2: AudioEffect.setEnabled(false) safety check
stage "AudioEffect disable safety"
if [[ -n "$SWDAP_SO_PATH" && -f "$SWDAP_SO_PATH" ]]; then
  if strings "$SWDAP_SO_PATH" | grep -qE 'State::DRAINING|AHAL_DlbDapSwEffectImpl'; then
    warn "Detected AIDL drain path in libswdapaidl.so; keep config_dolby_disable_audio_effect=false."
  else
    note "No State::DRAINING symbol found; false is still safest unless your HAL needs setEnabled(false)."
  fi
else
  note "libswdapaidl.so path omitted; leave false for MediaTek DAX3 AIDL."
fi
ask DISABLE_AUDIO_EFFECT "config_dolby_disable_audio_effect [false/true, default false]:"
[[ -z "$DISABLE_AUDIO_EFFECT" ]] && DISABLE_AUDIO_EFFECT="false"
write_env DISABLE_AUDIO_EFFECT "$DISABLE_AUDIO_EFFECT"

# Stage 3: profile IDs and HAL hooks
stage "Profile IDs and HAL hooks"
suggested_reapply="false"
if [[ -n "$DAX_XML_PATH" && -f "$DAX_XML_PATH" ]] && command -v python3 >/dev/null 2>&1; then
  suggested_reapply=$(python3 - "$DAX_XML_PATH" << 'PYEOF'
import sys, xml.etree.ElementTree as ET
tree = ET.parse(sys.argv[1])
profs = [(p.attrib.get("id", "?"), p.attrib.get("name", "?")) for p in tree.findall(".//profile")]
print("  XML profiles:", ", ".join(f"{pid}={name}" for pid, name in profs), file=sys.stderr)
reapply = False
amounts = []
for p in tree.findall(".//profile"):
    for ep in p.findall(".//endpoint_type"):
        inc = ep.find("include")
        ieq_en = ep.find("ieq-enable")
        ieq_amt = ep.find("ieq-amount")
        if inc is not None and "ieq_preset" in inc.attrib and ieq_en is not None and ieq_en.attrib.get("value") == "false":
            reapply = True
        if ieq_amt is not None and ieq_amt.attrib.get("value", "").isdigit():
            amounts.append(int(ieq_amt.attrib["value"]))
val = "true" if reapply else "false"
print(f"  Suggested config_dolby_force_ieq_reapply: {val}", file=sys.stderr)
if amounts:
    print(f"  XML ieq-amount range: {min(amounts)}..{max(amounts)} (0 if any are 0)", file=sys.stderr)
print(val)
PYEOF
)
  [[ -z "$suggested_reapply" ]] && suggested_reapply="false"
fi
ask PROFILE_VALUES "Custom dolby_profile_values CSV (blank keeps default 0,1,2,8):"
PROFILE_ENTRIES=""
if [[ -n "$PROFILE_VALUES" ]]; then
  ask PROFILE_ENTRIES "dolby_profile_entries tokens CSV (e.g. dynamic,video,music,voice):"
fi
ask FORCE_IEQ_REAPPLY "config_dolby_force_ieq_reapply [false/true, default ${suggested_reapply}]:"
[[ -z "$FORCE_IEQ_REAPPLY" ]] && FORCE_IEQ_REAPPLY="$suggested_reapply"
ask MIN_IEQ_AMOUNT "config_dolby_min_ieq_amount [integer, default 0]:"
[[ -z "$MIN_IEQ_AMOUNT" ]] && MIN_IEQ_AMOUNT="0"
ask PORT_STEREO_WIDENING "config_dolby_port_stereo_widening [false/true, default false]:"
[[ -z "$PORT_STEREO_WIDENING" ]] && PORT_STEREO_WIDENING="false"
write_env PROFILE_VALUES "$PROFILE_VALUES"
write_env PROFILE_ENTRIES "$PROFILE_ENTRIES"
write_env FORCE_IEQ_REAPPLY "$FORCE_IEQ_REAPPLY"
write_env MIN_IEQ_AMOUNT "$MIN_IEQ_AMOUNT"
write_env PORT_STEREO_WIDENING "$PORT_STEREO_WIDENING"

# Stage 4: per-profile XML defaults
stage "Per-profile XML defaults"
PROFILE_DEFAULTS_CSV=""
if [[ -n "$DAX_XML_PATH" && -f "$DAX_XML_PATH" ]] && command -v python3 >/dev/null 2>&1; then
  target_ids="${PROFILE_VALUES:-0,1,2,8}"
  PROFILE_DEFAULTS_CSV=$(python3 - "$DAX_XML_PATH" "$target_ids" << 'PYEOF'
import sys, xml.etree.ElementTree as ET
tree = ET.parse(sys.argv[1])
wanted = [x.strip() for x in sys.argv[2].split(",") if x.strip()]
items = []
for pid in wanted:
    p = tree.find(f".//profile[@id='{pid}']")
    if p is None:
        continue
    spk = p.find(".//endpoint_type[@id='speaker']")
    hp = p.find(".//endpoint_type[@id='headphone']")
    ep = spk if spk is not None else hp
    if ep is None:
        continue
    def val(node, tag, default="false"):
        el = node.find(tag) if node is not None else None
        return el.attrib.get("value", default) if el is not None else default
    ieq_on = val(ep, "ieq-enable", "false") == "true"
    inc = ep.find("include")
    ieq_id = inc.attrib.get("ieq_preset", "0") if (ieq_on and inc is not None) else "0"
    de_on = val(ep, "dialog-enhancer-enable", "false") == "true"
    de_amt = val(ep, "dialog-enhancer-amount", "0") if de_on else "0"
    bass = val(ep, "bass-enhancer-enable", "false")
    stereo = val(hp or ep, "headphone-virtualizer-steerer-source-distance", "0")
    vol = val(ep, "volume-leveler-enable", "false")
    hp_v = val(hp, "virtualizer-enable", "false") if hp is not None else "false"
    spk_v = val(spk, "virtualizer-enable", "false") if spk is not None else "false"
    items.append(f"{pid}:{ieq_id},{de_amt},{bass},{stereo},{vol},{hp_v},{spk_v}")
print(";".join(items))
PYEOF
)
  say "Suggested config_dolby_profile_defaults entries:"
  IFS=';' read -r -a _preview_items <<< "$PROFILE_DEFAULTS_CSV"
  for item in "${_preview_items[@]}"; do
    [[ -n "$item" ]] && step "$item"
  done
else
  note "dax-default.xml not provided; skipping XML default extraction."
fi
ask INCLUDE_PROFILE_DEFAULTS "Include config_dolby_profile_defaults in config.xml? [yes/no, default yes]:"
[[ -z "$INCLUDE_PROFILE_DEFAULTS" ]] && INCLUDE_PROFILE_DEFAULTS="yes"
write_env INCLUDE_PROFILE_DEFAULTS "$INCLUDE_PROFILE_DEFAULTS"

# Stage 5: generate overlay files
stage "Write overlay files"
CAP_DEVICE="$(printf '%s' "$DEVICE_CODENAME" | awk '{print toupper(substr($0,1,1)) substr($0,2)}')"
OVERLAY_NAME="DolbyOverlay${CAP_DEVICE}"
OVERLAY_DIR="${DEVICE_TREE_DIR}/overlays/${OVERLAY_NAME}"
say "Target overlay directory: ${OVERLAY_DIR}"
if confirm "Write ${OVERLAY_NAME} into ${OVERLAY_DIR}?"; then
  mkdir -p "${OVERLAY_DIR}/res/values"
  cat > "${OVERLAY_DIR}/Android.bp" << BPEOF
//
// Copyright (C) 2026 The LineageOS Project
//
// SPDX-License-Identifier: Apache-2.0
//

runtime_resource_overlay {
    name: "${OVERLAY_NAME}",
    vendor: true,
}
BPEOF

  cat > "${OVERLAY_DIR}/AndroidManifest.xml" << MEEOF
<?xml version="1.0" encoding="utf-8"?>
<!--
     Copyright (C) 2026 The LineageOS Project

     SPDX-License-Identifier: Apache-2.0
-->
<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    package="org.hlcyn.dolby.${DEVICE_CODENAME}.overlay">
    <application android:hasCode="false" />
    <overlay
        android:targetPackage="org.hlcyn.dolby"
        android:isStatic="true"
        android:priority="100" />
</manifest>
MEEOF

  {
    echo '<?xml version="1.0" encoding="utf-8"?>'
    echo '<resources>'
    echo "    <bool name=\"config_dolby_disable_audio_effect\">${DISABLE_AUDIO_EFFECT}</bool>"
    echo "    <bool name=\"config_dolby_force_ieq_reapply\">${FORCE_IEQ_REAPPLY}</bool>"
    if [[ "$MIN_IEQ_AMOUNT" != "0" ]]; then
      echo "    <integer name=\"config_dolby_min_ieq_amount\">${MIN_IEQ_AMOUNT}</integer>"
    fi
    if [[ "$PORT_STEREO_WIDENING" == "true" ]]; then
      echo "    <bool name=\"config_dolby_port_stereo_widening\">true</bool>"
    fi
    if [[ "$INCLUDE_PROFILE_DEFAULTS" == "yes" && -n "$PROFILE_DEFAULTS_CSV" ]]; then
      echo '    <string-array name="config_dolby_profile_defaults" translatable="false">'
      IFS=';' read -r -a _cfg_items <<< "$PROFILE_DEFAULTS_CSV"
      for item in "${_cfg_items[@]}"; do
        [[ -n "$item" ]] && echo "        <item>${item}</item>"
      done
      echo '    </string-array>'
    fi
    echo '</resources>'
  } > "${OVERLAY_DIR}/res/values/config.xml"

  if [[ -n "$PROFILE_VALUES" && -n "$PROFILE_ENTRIES" ]]; then
    {
      echo '<?xml version="1.0" encoding="utf-8"?>'
      echo '<resources>'
      echo '    <string-array name="dolby_profile_entries" translatable="false">'
      IFS=',' read -r -a _ent_items <<< "$PROFILE_ENTRIES"
      for item in "${_ent_items[@]}"; do
        echo "        <item>${item// /}</item>"
      done
      echo '    </string-array>'
      echo '    <string-array name="dolby_profile_values" translatable="false">'
      IFS=',' read -r -a _val_items <<< "$PROFILE_VALUES"
      for item in "${_val_items[@]}"; do
        echo "        <item>${item// /}</item>"
      done
      echo '    </string-array>'
      echo '</resources>'
    } > "${OVERLAY_DIR}/res/values/arrays.xml"
  fi

  wrote_overlay=1
else
  wrote_overlay=0
  SKIPPED+=("Write ${OVERLAY_NAME} files")
  warn "Skipped writing ${OVERLAY_DIR}."
fi

pause "Press Enter to view summary"
finish
if [[ "${wrote_overlay:-0}" -eq 1 ]]; then
  say "Add to ${DEVICE_TREE_DIR}/device.mk:"
  step "PRODUCT_PACKAGES += ${OVERLAY_NAME}"
  say "Build and verify over ADB:"
  step "m HalcyonDolby ${OVERLAY_NAME}"
  step "adb shell cmd overlay list | grep -i dolby"
fi
